const config = require('../config/config');

const User = require('../models/User');
const { validationResult } = require('express-validator');


class AuthController {
    static showRegister(req, res) {
        res.render('register', {
            title: 'User Registration',
            errors: [],
            formData: {}
        });
    }

    static async register(req, res) {
        const errors = validationResult(req);

        if (!errors.isEmpty()) {
            return res.render('register', {
                title: 'User Registration',
                errors: errors.array(),
                formData: req.body
            });
        }

        const { username, email, password, type, invitationCode, displayName, department } = req.body;

        try {
            const existingUser = await User.findByUsername(username);
            if (existingUser) {
                return res.render('register', {
                    title: 'User Registration',
                    errors: [{ msg: 'Username already exists' }],
                    formData: req.body
                });
            }

            const existingEmail = await User.findByEmail(email);
            if (existingEmail) {
                return res.render('register', {
                    title: 'User Registration',
                    errors: [{ msg: 'Email already registered' }],
                    formData: req.body
                });
            }


            if (parseInt(type) === 0) {
                if (!invitationCode || invitationCode !== config.getInviteCode()) {
                    return res.render('register', {
                        title: 'User Registration',
                        errors: [{ msg: 'Invalid invitation code' }],
                        formData: req.body
                    });
                }

            }

            req.session.userId = await User.create({
                username,
                email,
                password,
                type,
                displayName: displayName || username,
                department,
                role: 'user'
            });
            req.session.username = username;
            req.session.userType = type;
            req.session.userRole = 'user';

            res.redirect('/portal');
        } catch (error) {
            console.error('[Auth] User registration failed:', error.message);
            console.error(error);
            res.render('register', {
                title: 'User Registration',
                errors: [{ msg: 'Registration failed, please try again later' }],
                formData: req.body
            });
        }
    }

    static showLogin(req, res) {
        const samlRequest = req.query.SAMLRequest || '';
        const relayState = req.query.RelayState || '';
        const oauth2Params = {
            clientId: req.query.client_id || '',
            redirectUri: req.query.redirect_uri || '',
            responseType: req.query.response_type || '',
            state: req.query.state || '',
            scope: req.query.scope || ''
        };

        res.render('login', {
            title: 'User Login',
            errors: [],
            formData: {},
            samlRequest,
            relayState,
            oauth2Params
        });
    }

    static async login(req, res) {
        const { username, password } = req.body;
        const samlRequest = req.body.samlRequest || '';
        const relayState = req.body.relayState || '';

        try {
            const user = await User.findByUsername(username);

            if (!user) {
                return res.render('login', {
                    title: 'User Login',
                    errors: [{ msg: 'Invalid username or password' }],
                    formData: { username },
                    samlRequest,
                    relayState,
                    oauth2Params: {}
                });
            }

            const isValidPassword = await User.verifyPassword(password, user.password);

            if (!isValidPassword) {
                return res.render('login', {
                    title: 'User Login',
                    errors: [{ msg: 'Invalid username or password' }],
                    formData: { username },
                    samlRequest,
                    relayState,
                    oauth2Params: {}
                });
            }

            await User.updateLastLogin(user.id);

            req.session.userId = user.id;
            req.session.username = user.username;
            req.session.userType = user.type;
            req.session.userRole = user.role;
            req.session.userEmail = user.email;
            req.session.displayName = user.display_name || user.username;

            if (samlRequest) {
                return res.redirect(`/saml/sso?SAMLRequest=${encodeURIComponent(samlRequest)}&RelayState=${encodeURIComponent(relayState)}`);
            }

            const oauth2ClientId = req.body.oauth2ClientId || req.query.client_id;
            if (oauth2ClientId) {
                const params = new URLSearchParams({
                    client_id: oauth2ClientId,
                    redirect_uri: req.body.oauth2RedirectUri || req.query.redirect_uri,
                    response_type: req.body.oauth2ResponseType || req.query.response_type || 'code',
                    state: req.body.oauth2State || req.query.state || '',
                    scope: req.body.oauth2Scope || req.query.scope || 'profile'
                });
                return res.redirect(`/oauth/authorize?${params.toString()}`);
            }

            res.redirect('/portal');
        } catch (error) {
            console.error('[Auth] User login failed:', error.message);
            console.error(error);
            res.render('login', {
                title: 'User Login',
                errors: [{ msg: 'Login failed, please try again later' }],
                formData: { username },
                samlRequest,
                relayState,
                oauth2Params: {}
            });
        }
    }

    static async logout(req, res) {
        req.session.destroy((err) => {
            if (err) {
                console.error('[Auth] Session destroy failed:', err.message);
            }
            res.redirect('/');
        });
    }

    static async getCurrentUser(req, res) {
        try {
            const user = await User.findById(req.session.userId);

            if (!user) {
                return res.status(404).json({ error: 'User does not exist' });
            }

            res.json({
                success: true,
                data: User.sanitizeUser(user)
            });
        } catch (error) {
            console.error('[Auth] Get current user failed:', error.message);
            console.error(error);
            res.status(500).json({ error: 'Server error' });
        }
    }
}

module.exports = AuthController;

const SAMLIdentityProvider = require('../utils/saml');
const config = require('../config/config');

class SAMLService {
    static getIdentityProvider() {
        if (!this.idp) {
            const certificate = config.getCertificate();
            const privateKey = config.getPrivateKey();
            const samlConfig = config.getSamlConfig();

            this.idp = new SAMLIdentityProvider({
                issuer: process.env.SAML_ISSUER || samlConfig.issuer,
                certificate: certificate,
                privateKey: privateKey
            });
        }
        return this.idp;
    }

    static async generateSAMLResponse(user, options = {}) {
        const idp = this.getIdentityProvider();

        const userInfo = {
            id: user.id,
            uid: String(user.id || ''),
            username: user.username || '',
            email: user.email || user.username || '',
            displayName: user.display_name || user.username || '',
            display_name: user.display_name || user.username || '',
            role: user.role || 'user',
            department: user.department || ''
        };

        const responseOptions = {
            requestId: options.requestId,
            acsUrl: options.acsUrl || options.acs_url,
            destination: options.acsUrl || options.acs_url,
            entityId: options.entityId || options.entity_id,
            audience: options.entityId || options.entity_id,
            nameIDFormat: options.nameIDFormat || 'urn:oasis:names:tc:SAML:1.1:nameid-format:unspecified'
        };

        const responseXml = idp.createLoginResponse(userInfo, responseOptions);
        return SAMLIdentityProvider.encodeResponse(responseXml);
    }

    static async parseSAMLRequest(samlRequest, binding = 'redirect') {
        try {
            const idp = this.getIdentityProvider();
            const parsed = idp.parseAuthnRequest(samlRequest, binding);

            return {
                requestId: parsed.requestId,
                acsUrl: parsed.acsUrl,
                entityId: parsed.issuer,
                issueInstant: parsed.issueInstant,
                destination: parsed.destination,
                protocolBinding: parsed.protocolBinding,
                forceAuthn: parsed.forceAuthn,
                isPassive: parsed.isPassive,
                nameIDFormat: parsed.nameIDFormat,
                allowCreate: parsed.allowCreate
            };
        } catch (error) {
            console.error('[SAML Service] Failed to parse SAML request:', error.message);
            return null;
        }
    }

    static async validateSAMLRequest(samlRequest) {
        if (!samlRequest) {
            return { valid: false, message: 'Missing SAML request' };
        }

        try {
            const parsed = await this.parseSAMLRequest(samlRequest);
            if (!parsed) {
                return { valid: false, message: 'Invalid SAML request format' };
            }
            return { valid: true, data: parsed };
        } catch (error) {
            console.error('[SAML Service] SAML request validation failed:', error.message);
            return { valid: false, message: error.message };
        }
    }

    static async validateRequestId(requestId, issueInstant) {
        const idp = this.getIdentityProvider();
        return idp.validateRequestId(requestId, issueInstant);
    }

    static generateMetadata() {
        try {
            const idp = this.getIdentityProvider();
            const serverConfig = config.getServerConfig();
            const samlConfig = config.getSamlConfig();
            const baseUrl = process.env.BASE_URL || `http://${serverConfig.host}:${serverConfig.port}`;

            return idp.getMetadata({
                entityID: process.env.SAML_ISSUER || samlConfig.issuer,
                ssoLocation: `${baseUrl}/saml/sso`,
                sloLocation: `${baseUrl}/saml/slo`,
                nameIDFormats: ['urn:oasis:names:tc:SAML:1.1:nameid-format:unspecified']
            });
        } catch (error) {
            console.error('[SAML Service] Failed to generate metadata:', error.message);
            console.error(error);
            throw error;
        }
    }

    static async generateSAMLLogoutResponse(options = {}) {
        try {
            const idp = this.getIdentityProvider();

            const logoutResponseOptions = {
                inResponseTo: options.inResponseTo,
                destination: options.destination || options.acsUrl
            };

            const responseXml = idp.createLogoutResponse(logoutResponseOptions);
            return responseXml;
        } catch (error) {
            console.error('[SAML Service] Failed to generate logout response:', error.message);
            console.error(error);
            throw error;
        }
    }

    static encodeSAMLResponse(samlResponse) {
        return SAMLIdentityProvider.encodeResponse(samlResponse);
    }

    static decodeSAMLRequest(samlRequest) {
        try {
            return SAMLIdentityProvider.decodeRequest(samlRequest, 'redirect');
        } catch (error) {
            console.error('[SAML Service] Failed to decode SAML request:', error.message);
            return null;
        }
    }
}

module.exports = SAMLService;

const pool = require('../config/database');
const bcrypt = require('bcrypt');

class User {
    static async create({ username, email, password, type, displayName, department, role = 'user' }) {
        const hashedPassword = await bcrypt.hash(password, 10);

        const [result] = await pool.query(
            `INSERT INTO users (username, email, password, type, display_name, department, role)
       VALUES (?, ?, ?, ?, ?, ?, ?)`,
            [username, email, hashedPassword, type, displayName, department, role]
        );

        return result.insertId;
    }

    static async findByUsername(username) {
        const [rows] = await pool.query(
            'SELECT * FROM users WHERE username = ? AND status = 1',
            [username]
        );
        return rows[0];
    }

    static async findByEmail(email) {
        const [rows] = await pool.query(
            'SELECT * FROM users WHERE email = ? AND status = 1',
            [email]
        );
        return rows[0];
    }

    static async findById(id) {
        const [rows] = await pool.query(
            'SELECT * FROM users WHERE id = ? AND status = 1',
            [id]
        );
        return rows[0];
    }

    static async verifyPassword(plainPassword, hashedPassword) {
        return bcrypt.compare(plainPassword, hashedPassword);
    }

